def solve(value):
    if not value:
        return ""

    first = value[0]
    shortest_length = min(len(word) for word in value)

    for position in range(shortest_length):
        character = first[position]
        for word in value:
            if word[position] != character:
                return first[:position]

    return first[:shortest_length]
